"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[38458],{3331:(e,a,o)=>{o.d(a,{R:()=>r,x:()=>l});var n=o(36672);const s={},i=n.createContext(s);function r(e){const a=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function l(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(i.Provider,{value:a},e.children)}},79428:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>d,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>n,toc:()=>c});const n=JSON.parse('{"id":"2023/04/13","title":"2023-04-13","description":"Semaphore: Un teclado de cuerpo entero","source":"@site/i18n/es/docusaurus-plugin-content-docs/current/2023/04/13.md","sourceDirName":"2023/04","slug":"/2023/04/13","permalink":"/es/2023/04/13","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/es/docusaurus-plugin-content-docs//current/2023/04/13.md","tags":[],"version":"current","frontMatter":{"localized_date":"13 de abril de 2023","top_news":"Semaphore: Un teclado de cuerpo entero"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-14","permalink":"/es/2023/04/14"},"next":{"title":"2023-04-12","permalink":"/es/2023/04/12"}}');var s=o(23420),i=o(3331);const r={localized_date:"13 de abril de 2023",top_news:"Semaphore: Un teclado de cuerpo entero"},l="2023-04-13",d={},c=[{value:"Semaphore: Un teclado de cuerpo entero",id:"semaphore-un-teclado-de-cuerpo-entero",level:2},{value:"Mostrar GPT-4-powered web searches for developers (en ingl\xe9s)",id:"mostrar-gpt-4-powered-web-searches-for-developers-en-ingl\xe9s",level:2},{value:"Sustituyendo a mis mejores amigos por un LLM entrenado en 500k mensajes de chat de grupo",id:"sustituyendo-a-mis-mejores-amigos-por-un-llm-entrenado-en-500k-mensajes-de-chat-de-grupo",level:2},{value:"NPR abandona Twitter tras ser tachada de &#39;medio de comunicaci\xf3n afiliado al Estado&#39;",id:"npr-abandona-twitter-tras-ser-tachada-de-medio-de-comunicaci\xf3n-afiliado-al-estado",level:2},{value:"Despidos masivos y jefes ausentes crean una crisis de moral en Meta",id:"despidos-masivos-y-jefes-ausentes-crean-una-crisis-de-moral-en-meta",level:2},{value:"Hetzner presenta servidores en nube ARM64",id:"hetzner-presenta-servidores-en-nube-arm64",level:2},{value:"El nuevo director de la NASA jura sobre el &#39;Pale Blue Dot&#39; de Carl Sagan en lugar de la Biblia",id:"el-nuevo-director-de-la-nasa-jura-sobre-el-pale-blue-dot-de-carl-sagan-en-lugar-de-la-biblia",level:2},{value:"Intel Foundry Services y Arm anuncian su colaboraci\xf3n en el dise\xf1o de SoC",id:"intel-foundry-services-y-arm-anuncian-su-colaboraci\xf3n-en-el-dise\xf1o-de-soc",level:2},{value:"Un jugador de EVE Online utiliza una regla poco conocida para llevar a cabo el mayor atraco de la historia del juego",id:"un-jugador-de-eve-online-utiliza-una-regla-poco-conocida-para-llevar-a-cabo-el-mayor-atraco-de-la-historia-del-juego",level:2},{value:"Los hilos virtuales llegan al JDK 21 y marcan el comienzo de una nueva era de la concurrencia",id:"los-hilos-virtuales-llegan-al-jdk-21-y-marcan-el-comienzo-de-una-nueva-era-de-la-concurrencia",level:2}];function t(e){const a={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"2023-04-13",children:"2023-04-13"})}),"\n",(0,s.jsx)(a.h2,{id:"semaphore-un-teclado-de-cuerpo-entero",children:"Semaphore: Un teclado de cuerpo entero"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://github.com/everythingishacked/Semaphore",children:"Original"}),'.\nSemaphore es un teclado de cuerpo completo que utiliza OpenCV y la detecci\xf3n de Pose de MediaPipe para detectar puntos de referencia del cuerpo a partir de la entrada de v\xeddeo, calcular las diferencias relativas, y traducirlas en teclas y comandos enviados a trav\xe9s del teclado. La entrada principal consiste en "teclear" letras, d\xedgitos y s\xedmbolos a trav\xe9s del sem\xe1foro de banderas extendiendo ambos brazos en varios \xe1ngulos, con otros gestos modificadores incluidos para funciones como may\xfasculas, retroceso y teclas de flecha. Funciona con los \xfaltimos MacOS y se puede acceder a \xe9l a trav\xe9s del terminal con el uso de una biblioteca de teclado personalizada.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35536550",children:"Discussion Service"}),".\nUn sistema de teclado llamado Semaphore, que utiliza gestos f\xedsicos, ha recibido comentarios positivos de los usuarios de Discussion Service y tiene implicaciones para los trabajadores remotos que quieren combinar el ejercicio f\xedsico y la programaci\xf3n. Los usuarios hablan de combinar Semaphore con taquigraf\xeda, notas musicales, ejercicios de yoga y programaci\xf3n, y algunos se\xf1alan el potencial para aumentar la eficiencia mediante la adici\xf3n de funciones como autocompletar."]}),"\n",(0,s.jsx)(a.h2,{id:"mostrar-gpt-4-powered-web-searches-for-developers-en-ingl\xe9s",children:"Mostrar GPT-4-powered web searches for developers (en ingl\xe9s)"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.phind.com",children:"Original"}),".\nEl sitio web 'phind.com' es actualmente inaccesible, ya que est\xe1 utilizando un servicio de seguridad para protegerse de ataques en l\xednea que pueden haber sido desencadenados por ciertas acciones, como el env\xedo de una determinada palabra o frase, un comando SQL o datos malformados. Para solucionarlo, los usuarios pueden enviar un correo electr\xf3nico al propietario del sitio e incluir detalles de lo que estaban haciendo cuando se produjo el bloqueo y el ID de rayo de Cloudflare que se encuentra en la parte inferior de la p\xe1gina."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35543668",children:"Discussion Service"}),".\nEl motor de b\xfasqueda GPT-4 de Phind.com ofrece respuestas de codificaci\xf3n precisas y explicaciones detalladas a trav\xe9s de filtros personalizados, y se han explorado modelos de reparto de ingresos para los productores de contenidos, aunque existe preocupaci\xf3n por los costes de modelado; los usuarios han elogiado el servicio por su informaci\xf3n clara, eficiencia y valiosa informaci\xf3n complementaria, aunque se han se\xf1alado algunos problemas de precisi\xf3n en las consultas. Algunos usuarios han criticado la capacidad de GPT-4 para resolver problemas y han cuestionado su precisi\xf3n y relevancia, pero el equipo de Phind ha respondido lanzando una nueva versi\xf3n con una funci\xf3n de modo experto."]}),"\n",(0,s.jsx)(a.h2,{id:"sustituyendo-a-mis-mejores-amigos-por-un-llm-entrenado-en-500k-mensajes-de-chat-de-grupo",children:"Sustituyendo a mis mejores amigos por un LLM entrenado en 500k mensajes de chat de grupo"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.izzy.co/blogs/robo-boys.html",children:"Original"}),".\nSe entren\xf3 un LLM en los mensajes de chat de grupo sin censura de la \xe9poca universitaria de Izzy Miller, lo que dio como resultado mejores conversaciones con sus mejores amigos. El conjunto de datos constaba de 500.000 mensajes, y Miller lo sesion\xf3 para facilitar el modelado. El modelo resultante gener\xf3 conversaciones enteras, capturando la esencia contextual del chat de grupo, y el art\xedculo explica c\xf3mo convertir los pesos LLaMA en un formato compatible con la biblioteca Transformers mediante codificaci\xf3n Python, incluida la importancia de un aprovisionamiento adecuado de espacio en disco."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35540154",children:"Discussion Service"}),".\nAlgunos usuarios de Discussion Service expresan su preocupaci\xf3n por las implicaciones \xe9ticas de crear copias digitales de individuos utilizando datos personales, mientras que otros argumentan que las leyes existentes y la presi\xf3n moral/social siguen siendo aplicables. Los cr\xedticos advierten de posibles aplicaciones nefastas de la tecnolog\xeda de Discussion Service por parte de reg\xedmenes autocr\xe1ticos o con fines lucrativos. Han surgido debates divisivos sobre la tecnolog\xeda de IA, con preocupaciones sobre su impacto no probado en la privacidad e hiperescepticismo en torno a su eficacia. Hay controversia en torno al uso de chatbots de IA y su potencial para sustituir las conexiones humanas, as\xed como preocupaciones \xe9ticas sobre las herramientas de completado de texto que permiten la creaci\xf3n de simulaciones digitales de seres queridos perdidos."]}),"\n",(0,s.jsx)(a.h2,{id:"npr-abandona-twitter-tras-ser-tachada-de-medio-de-comunicaci\xf3n-afiliado-al-estado",children:"NPR abandona Twitter tras ser tachada de 'medio de comunicaci\xf3n afiliado al Estado'"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.wbur.org/npr/1169269161/npr-leaves-twitter-government-funded-media-label",children:"Original"}),'.\nNPR detuvo su actividad en Twitter despu\xe9s de que Twitter los etiquetara como "medios de comunicaci\xf3n afiliados al Estado", una etiqueta que NPR considera inexacta y enga\xf1osa. Esta decisi\xf3n protege la credibilidad de NPR y garantiza que puedan producir periodismo sin negatividad. Elon Musk admiti\xf3 que quiz\xe1 se equivoc\xf3 con la etiqueta y puede que la cambie por "financiada con fondos p\xfablicos".']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35539280",children:"Discussion Service"}),'.\nNPR se enfrent\xf3 a cr\xedticas y finalmente abandon\xf3 Twitter tras ser etiquetada como "medio de comunicaci\xf3n afiliado al Estado" debido a la financiaci\xf3n gubernamental, lo que llev\xf3 a un debate sobre los criterios para tal etiquetado y si caracteriza con precisi\xf3n a NPR como una organizaci\xf3n de noticias con independencia editorial. Algunos usuarios de Discussion Service sugieren que otras compa\xf1\xedas, incluidas las empresas de Elon Musk, entran en esta categor\xeda debido a la financiaci\xf3n gubernamental. Los comentarios tambi\xe9n ponen de relieve la compleja relaci\xf3n entre los medios de comunicaci\xf3n, las fuentes de financiaci\xf3n y la independencia editorial, ya que algunos acusan a NPR de parcialidad izquierdista y otros defienden su transparencia e independencia.']}),"\n",(0,s.jsx)(a.h2,{id:"despidos-masivos-y-jefes-ausentes-crean-una-crisis-de-moral-en-meta",children:"Despidos masivos y jefes ausentes crean una crisis de moral en Meta"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html",children:"Original"}),".\nLa moral est\xe1 por los suelos en la empresa matriz de Facebook, Meta, debido a los despidos masivos y a los jefes ausentes que causan inquietud entre los trabajadores. Los empleados tambi\xe9n cuestionan la direcci\xf3n de la empresa."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35537813",children:"Discussion Service"}),".\nLos expertos debaten diversas opiniones sobre el futuro de tecnolog\xedas punteras como la IA generativa, la RV y las criptomonedas. Mientras algunos defienden casos de uso espec\xedficos de la IA generativa y avances en los medios generativos, surgen dudas sobre su potencial para automatizar empleos de clase media y la precisi\xf3n de los modelos de IA generativa. Las empresas esperan que la IA generativa ayude a acelerar el mercado de la tecnolog\xeda AR/VR, y el \xe9xito de los dispositivos de Meta Labs se contrapone al incierto \xe9xito de los auriculares de Apple. La industria de las criptomonedas es vista como una estafa por afinidad por algunos, pero Bitcoin sigue siendo visto de manera diferente por otros."]}),"\n",(0,s.jsx)(a.h2,{id:"hetzner-presenta-servidores-en-nube-arm64",children:"Hetzner presenta servidores en nube ARM64"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.hetzner.com/press-release/arm64-cloud/",children:"Original"}),".\nEl proveedor alem\xe1n de hosting y cloud Hetzner ha lanzado cuatro nuevos servidores Hetzner Cloud basados en tecnolog\xeda Arm64, lo que supone el primer uso de estos procesadores por parte de la empresa. Los servidores ofrecen hasta 16 vCPU y se combinan con hasta 32 GB de RAM ECC y hasta 320 GB de almacenamiento basado en SSD NVMe. La nueva l\xednea de servidores comienza con un precio de 3,79 \u20ac (4,54 $) al mes, y cuenta con opciones de facturaci\xf3n por horas que reducir\xe1n los costes para los clientes."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35540084",children:"Discussion Service"}),".\nHetzner ha lanzado servidores en nube ARM64 m\xe1s baratos y con mejores prestaciones que AWS. La infraestructura en la nube tiene opiniones encontradas, ya que algunos defienden la fiabilidad y la escalabilidad, mientras que otros consideran que las configuraciones m\xe1s sencillas son m\xe1s fiables y rentables. La oferta de Hetzner llena un vac\xedo para quienes quieren ejecutar Docker sin configurar todos los servicios, pero puede no ser adecuada para empresas preocupadas por la seguridad debido a un control de acceso f\xedsico m\xe1s d\xe9bil. Algunos han denunciado prohibiciones de cuentas debido a la estricta pol\xedtica de fraude de Hetzner, y hay dudas sobre la sostenibilidad de los bajos precios en Europa debido a los elevados costes energ\xe9ticos."]}),"\n",(0,s.jsx)(a.h2,{id:"el-nuevo-director-de-la-nasa-jura-sobre-el-pale-blue-dot-de-carl-sagan-en-lugar-de-la-biblia",children:"El nuevo director de la NASA jura sobre el 'Pale Blue Dot' de Carl Sagan en lugar de la Biblia"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.independent.co.uk/space/nasa-director-carl-sagan-oath-b2317698.html",children:"Original"}),'.\nMakenzie Lystrup, la reci\xe9n nombrada directora del Centro Goddard de Vuelos Espaciales de la NASA, ha prestado un juramento poco convencional utilizando el libro de Carl Sagan de 1994 "Pale Blue Dot" en lugar de la Biblia. El libro del astr\xf3nomo se inspira en la famosa fotograf\xeda de la Tierra Pale Blue Dot tomada en 1990 por la sonda espacial Voyager 1, y Lystrup afirma estar "muy centrado en hacer crecer la pr\xf3xima generaci\xf3n de innovadores". La plantilla del Centro Goddard de Vuelos Espaciales consta de 10.000 empleados, tanto funcionarios como contratistas, y el centro es responsable de la ejecuci\xf3n de una cartera de 4.000 millones de d\xf3lares.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35536612",children:"Discussion Service"}),'.\nEl nuevo director de la NASA prest\xf3 juramento sobre el "Pale Blue Dot" de Carl Sagan, suscitando un debate sobre la eficacia de los juramentos, el significado de los textos sagrados, los valores personales frente a los textos religiosos y el verdadero significado de la responsabilidad personal. Algunos sostienen que jurar sobre un libro que represente los valores de uno es m\xe1s apropiado, mientras que otros consideran necesario contar con la representaci\xf3n de una deidad como garante del juramento. Jurar tiene funciones rituales y se ha utilizado para dar forma a las sociedades y a la historia, pero en \xfaltima instancia, el art\xedculo no contiene informaci\xf3n nueva o apasionante para los expertos en la materia.']}),"\n",(0,s.jsx)(a.h2,{id:"intel-foundry-services-y-arm-anuncian-su-colaboraci\xf3n-en-el-dise\xf1o-de-soc",children:"Intel Foundry Services y Arm anuncian su colaboraci\xf3n en el dise\xf1o de SoC"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry-arm-announce-multigeneration-collaboration-leading-edge-soc-design.html",children:"Original"}),".\nIntel Foundry Services (IFS) y Arm han acordado una colaboraci\xf3n multigeneraci\xf3n para permitir el desarrollo de system-on-chips (SoCs) de computaci\xf3n de bajo consumo para dispositivos m\xf3viles y otras industrias. La colaboraci\xf3n combinar\xe1 los procesadores seguros y energ\xe9ticamente eficientes de Arm con la huella de fabricaci\xf3n de IFS, que incluye capacidad en EE.UU. y la UE, ofreciendo nuevas tecnolog\xedas de transistores de vanguardia para mejorar la potencia y el rendimiento en el proceso Intel 18A. Esta colaboraci\xf3n permitir\xe1 una cadena de suministro global m\xe1s equilibrada para los clientes de fundici\xf3n que trabajan en el dise\xf1o de SoC m\xf3viles con n\xfacleos de CPU basados en Arm."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35539057",children:"Discussion Service"}),".\nIntel Foundry Services colabora con Arm en el dise\xf1o de SoCs, enfrent\xe1ndose a la competencia de TSMC, que cuenta con un historial de colaboraci\xf3n con Arm. Los usuarios de Discussion Service discuten los pros y los contras del Mac Studio y lo comparan con otras opciones de PC, con cr\xedticas a las limitaciones del Mac para juegos y software CAD. El art\xedculo y los comentarios cubren alternativas para la fabricaci\xf3n y los dispositivos IoT, la producci\xf3n del nodo de 2 nm de Intel y la especulaci\xf3n sobre la capacidad de Intel para cumplir sus promesas, al tiempo que se reconoce la importancia del consumo energ\xe9tico, el precio y la capacidad inal\xe1mbrica en el desarrollo de dispositivos IoT."]}),"\n",(0,s.jsx)(a.h2,{id:"un-jugador-de-eve-online-utiliza-una-regla-poco-conocida-para-llevar-a-cabo-el-mayor-atraco-de-la-historia-del-juego",children:"Un jugador de EVE Online utiliza una regla poco conocida para llevar a cabo el mayor atraco de la historia del juego"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.pcgamer.com/eve-online-player-uses-obscure-rule-to-pull-off-the-biggest-heist-in-the-games-history/",children:"Original"}),'.\nUn jugador de EVE Online ha llevado a cabo el mayor atraco de la historia del juego aprovech\xe1ndose de la "mec\xe1nica de las acciones", lo que le ha reportado un bot\xedn de m\xe1s de 22.300 d\xf3lares en dinero real. Para ello se hizo con el control de Event Horizon Expeditionaries utilizando una cuenta limpia, transfiriendo acciones y despojando a la cartera corporativa de 130.000 millones de ISK y m\xfaltiples naves, estimando el valor total del bot\xedn en 2,23 billones de ISK. El sistema de acciones es potencialmente muy f\xe1cil de explotar, seg\xfan un hilo de Reddit de 2014, y esta estrategia ya se ha probado antes.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35533711",children:"Discussion Service"}),".\nUn jugador orquest\xf3 un exitoso atraco en EVE Online, planteando preguntas en torno a su mec\xe1nica corporativa y los riesgos de explotaci\xf3n del juego. El atraco fue visto como algo genial y un punto culminante del juego, pero algunos critican el enfoque y la mec\xe1nica financiera del juego, incluyendo el valor de su moneda en el juego y su sistema de votaci\xf3n corporativa."]}),"\n",(0,s.jsx)(a.h2,{id:"los-hilos-virtuales-llegan-al-jdk-21-y-marcan-el-comienzo-de-una-nueva-era-de-la-concurrencia",children:"Los hilos virtuales llegan al JDK 21 y marcan el comienzo de una nueva era de la concurrencia"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"https://www.infoq.com/news/2023/04/virtual-threads-arrives-jdk21/",children:"Original"}),".\nN/A."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35535906",children:"Discussion Service"}),".\nLos hilos virtuales de JDK 21 reducen los hilos f\xedsicos para la concurrencia y la simplificaci\xf3n de aplicaciones io-intensivas, pero surgen debates sobre la gesti\xf3n de memoria. Java se compara con Go, y marcos como Spring, Spring Boot y Quarkus ofrecen alternativas a Ruby on Rails, mientras que el debate sobre Java frente a Go considera el rendimiento, la observabilidad, la solidez de los sistemas de tipos y la interoperabilidad. El art\xedculo reflexiona sobre el nicho de la categor\xeda JVM y c\xf3mo las distintas implementaciones pueden afectar a la experiencia del usuario, y menciona comparaciones con C# y JetBrains Rider."]})]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(t,{...e})}):t(e)}}}]);